DO $$DECLARE t record;src text;BEGIN EXECUTE format('CREATE OR REPLACE FUNCTION erp_access_private.domains() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path='''' AS %L','SELECT '||quote_literal(erp_access_private.domains()||ARRAY['finance'])||'::text[]');FOR t IN SELECT cl.relname FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE n.nspname='public' AND cl.relkind='r' AND cl.relname NOT LIKE 'erp_branch_%' AND EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=cl.oid AND a.attname='cafe_id' AND NOT a.attisdropped) LOOP EXECUTE format('CREATE OR REPLACE VIEW erp_branch_private.%I WITH(security_barrier=true) AS SELECT source.* FROM public.%I source WHERE nullif(current_setting(''erp.branch_cafe'',true),'''') IS DISTINCT FROM source.cafe_id::text OR erp_branch_private.row_allowed(source.cafe_id,erp_branch_private.current_branch(source.cafe_id),to_jsonb(source),'''')',t.relname,t.relname);END LOOP;END $$;